/**
 * components/ui/drawer.tsx
 *
 * Slide-over drawer — focus-trapped, scroll-lock safe.
 */
import { X } from 'lucide-react'
import * as React from 'react'

import { Portal } from '~/components/primitives/portal'
import { useLatest } from '~/hooks/use-latest'
import { cx } from '~/lib/cx'
import { lockBodyScroll, trapFocus } from '~/lib/overlay'
import styles from './drawer.module.scss'

export type DrawerSide = 'left' | 'right'

export interface DrawerProps {
  open: boolean
  onClose: () => void
  title?: string
  'aria-label'?: string
  hideClose?: boolean
  /** Slide-in edge. Default: left. */
  side?: DrawerSide
  className?: string
  children?: React.ReactNode
}

export function Drawer({
  open,
  onClose,
  title,
  'aria-label': ariaLabel,
  hideClose,
  side = 'left',
  className,
  children,
}: DrawerProps) {
  const titleId = React.useId()
  const [panel, setPanel] = React.useState<HTMLDivElement | null>(null)
  const onCloseRef = useLatest(onClose)

  React.useEffect(() => {
    if (!open || !panel) return
    const unlock = lockBodyScroll()
    const releaseTrap = trapFocus(panel, () => onCloseRef.current())
    return () => {
      releaseTrap()
      unlock()
    }
  }, [open, panel, onCloseRef])

  if (!open) return null

  const fromLeft = side === 'left'

  return (
    <Portal>
      <div
        className={styles.overlay}
        aria-hidden="true"
        onClick={() => onCloseRef.current()}
      />

      <div
        ref={setPanel}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-label={!title ? (ariaLabel ?? 'Drawer') : undefined}
        tabIndex={-1}
        className={cx(
          styles.panel,
          fromLeft ? styles.sideLeft : styles.sideRight,
          className,
        )}
      >
        <div className={styles.header}>
          {title ? (
            <h2 id={titleId} className={styles.title}>
              {title}
            </h2>
          ) : null}

          {hideClose ? null : (
            <button
              type="button"
              className={styles.close}
              onClick={() => onCloseRef.current()}
              aria-label="Close drawer"
            >
              <X aria-hidden />
            </button>
          )}
        </div>

        <div className={styles.body}>{children}</div>
      </div>
    </Portal>
  )
}

@use 'styles' as vz;

.overlay {
  position: fixed;
  inset: 0;
  z-index: vz.z('overlay');
  background: vz.color('foreground', 0.45);
  backdrop-filter: blur(6px);
  animation: vz-drawer-overlay-in vz.duration('base') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.panel {
  --vz-drawer-from: -100%;

  position: fixed;
  inset-block: 0;
  z-index: vz.z('modal');
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 24rem;
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(3);
  outline: none;
  animation: vz-drawer-in vz.duration('slow') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.side-left {
  --vz-drawer-from: -100%;

  left: 0;
  border-inline-end: 1px solid vz.color('border');
  border-start-end-radius: vz.radius('2xl');
  border-end-end-radius: vz.radius('2xl');
}

.side-right {
  --vz-drawer-from: 100%;

  right: 0;
  border-inline-start: 1px solid vz.color('border');
  border-start-start-radius: vz.radius('2xl');
  border-end-start-radius: vz.radius('2xl');
}

.header {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(3);
  padding: vz.space(4) vz.space(5);
  border-bottom: 1px solid vz.color('border');
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('base');
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.close {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(8);
  height: vz.space(8);
  margin-inline-start: auto;
  padding: 0;
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    @include vz.icon(5);
  }
}

.body {
  flex: 1;
  overflow-y: auto;

  @include vz.overscroll;
  @include vz.scrollbar(8px);
}

@keyframes vz-drawer-overlay-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes vz-drawer-in {
  from {
    opacity: 0.4;
    transform: translateX(var(--vz-drawer-from));
  }

  to {
    opacity: 1;
    transform: none;
  }
}
